effect.shader:
vec4 getBlured(float speedIn, vec2 texelSize, vec2 center, vec2 v) {
    float speed = speedIn;
    if(adaptive)
        speed *= length( acLayerNorm.st - center );
    else
        speed *= smoothstep( 0.0, length(texelSize)*5.0, length( acLayerNorm.st - center ));
    int nSamples = int(clamp(speed, 1.01, 100.01));
    vec4 outColor = texture2DCv(inputImg.texture,acScreenNorm.st);
    vec2 vnorm = normalize(v)*texelSize*speed;
    vec2 offsetScale = vec2(1., 1.);
    if( acScreenSize.y > acScreenSize.x ) {
        offsetScale.x *= acScreenSize.x / acScreenSize.y;
    } else {
        offsetScale.y *= acScreenSize.y / acScreenSize.x;
    }

    for(int i=1; i<nSamples; i++ ) {
        vec2 offset = vnorm * (float(i) / float(nSamples - 1) - 0.5);
        offset *= offsetScale;

        outColor += texture2DCv(inputImg.texture, acScreenNorm.st-offset);
    }
    return outColor/float(nSamples);
}

void main() {
    vec2 texelSize = 1.0 / getTexSize(inputImg.size);
    vec2 center = vec2(0.5 + centerPoint.x/500., 0.5 - centerPoint.y/500.);
    vec2 v = acScreenNorm.st - (vec4(center,0.0,1.0) * acLayerToScreen).xy;
    float speed_r = length((offset_r+strength) / 2.0 / texelSize);
    float speed_g = length((offset_g+strength) / 2.0 / texelSize);
    float speed_b = length((offset_b+strength) / 2.0 / texelSize);
    vec4 redBlurred = getBlured(speed_r, texelSize, center, v);
    vec4 greenBlurred = getBlured(speed_g, texelSize, center, v);
    vec4 blueBlurred = getBlured(speed_b, texelSize, center, v);
    gl_FragColor = vec4(redBlurred.r,
                        greenBlurred.g,
                        blueBlurred.b,
                        (redBlurred.a+greenBlurred.a+blueBlurred.a)/3.0);
}
